from pathlib import Path
import base64
import subprocess

ROOT = Path.cwd()
APP = ROOT / "frontend/src/App.jsx"
PROFILE = ROOT / "frontend/src/ProfilePanel.jsx"
PATHS = ROOT / "frontend/src/router/paths.js"
SHELL = ROOT / "frontend/src/layout/AppShell.jsx"
SIDEBAR = ROOT / "frontend/src/layout/Sidebar.jsx"
PUBLIC = ROOT / "frontend/public"
FRONTEND = ROOT / "frontend"

if not (ROOT / ".git").exists():
    raise RuntimeError("Execute este arquivo na raiz do RunCore.")

for path in [APP, PROFILE, PATHS, SHELL, SIDEBAR]:
    if not path.exists():
        raise RuntimeError(f"Arquivo não encontrado: {path}")

branch = subprocess.check_output(
    ["git", "branch", "--show-current"],
    cwd=ROOT,
    text=True,
).strip()

if branch != "main":
    raise RuntimeError(f"Branch atual: {branch}. Troque para main.")

PUBLIC.mkdir(parents=True, exist_ok=True)
(PUBLIC / "logo-symbol-mark.png").write_bytes(
    base64.b64decode("")
)

paths = PATHS.read_text(encoding="utf-8")
old_path = '''export const studentPaths = {
  dashboard: "/atleta/dashboard",'''
new_path = '''export const studentPaths = {
  completeProfile: "/atleta/completar-cadastro",
  dashboard: "/atleta/dashboard",'''

if old_path in paths:
    paths = paths.replace(old_path, new_path, 1)
elif 'completeProfile: "/atleta/completar-cadastro"' not in paths:
    raise RuntimeError("Não encontrei studentPaths no formato esperado.")

PATHS.write_text(paths, encoding="utf-8", newline="\n")

shell = SHELL.read_text(encoding="utf-8")
title_anchor = '''  "/atleta/dashboard": "Dashboard",'''
title_line = '''  "/atleta/completar-cadastro": "Complete seu cadastro",
  "/atleta/dashboard": "Dashboard",'''

if title_line not in shell:
    if title_anchor not in shell:
        raise RuntimeError("Não encontrei os títulos das rotas do aluno.")
    shell = shell.replace(title_anchor, title_line, 1)

old_signature = '''export default function AppShell({ user, onLogout, children }) {'''
new_signature = '''export default function AppShell({
  user,
  onLogout,
  children,
  onboarding = false,
}) {'''

if old_signature in shell:
    shell = shell.replace(old_signature, new_signature, 1)
elif "onboarding = false" not in shell:
    raise RuntimeError("Não encontrei a assinatura do AppShell.")

old_sidebar_call = '''<Sidebar role={user?.role} mobileOpen={mobileMenuOpen} onClose={() => setMobileMenuOpen(false)} />'''
new_sidebar_call = '''<Sidebar
        role={user?.role}
        mobileOpen={mobileMenuOpen}
        onClose={() => setMobileMenuOpen(false)}
        onboarding={onboarding}
      />'''

if old_sidebar_call in shell:
    shell = shell.replace(old_sidebar_call, new_sidebar_call, 1)
elif "onboarding={onboarding}" not in shell:
    raise RuntimeError("Não encontrei a chamada do Sidebar.")

SHELL.write_text(shell, encoding="utf-8", newline="\n")

sidebar = SIDEBAR.read_text(encoding="utf-8")
old_sidebar_signature = '''export default function Sidebar({ role, mobileOpen, onClose }) {'''
new_sidebar_signature = '''export default function Sidebar({
  role,
  mobileOpen,
  onClose,
  onboarding = false,
}) {'''

if old_sidebar_signature in sidebar:
    sidebar = sidebar.replace(
        old_sidebar_signature,
        new_sidebar_signature,
        1,
    )
elif "onboarding = false" not in sidebar:
    raise RuntimeError("Não encontrei a assinatura do Sidebar.")

old_nav_start = '''        <nav className="app-sidebar-nav" aria-label="Menu principal">'''
old_nav_end = '''        </nav>'''

if "{!onboarding && (" not in sidebar:
    start = sidebar.find(old_nav_start)
    if start < 0:
        raise RuntimeError("Não encontrei o início do menu lateral.")
    end = sidebar.find(old_nav_end, start)
    if end < 0:
        raise RuntimeError("Não encontrei o fim do menu lateral.")
    end += len(old_nav_end)
    nav_block = sidebar[start:end]
    wrapped = '''        {!onboarding && (
''' + nav_block + '''
        )}'''
    sidebar = sidebar[:start] + wrapped + sidebar[end:]

SIDEBAR.write_text(sidebar, encoding="utf-8", newline="\n")

app = APP.read_text(encoding="utf-8")
old_incomplete = '''    if (!studentProfileStatus.complete) {
      return (
        <AppShell
          user={currentUser}
          onLogout={studentLogout}
        >'''

new_incomplete = '''    if (!studentProfileStatus.complete) {
      if (
        location.pathname
        !== studentPaths.completeProfile
      ) {
        return (
          <Navigate
            to={studentPaths.completeProfile}
            replace
          />
        );
      }

      return (
        <AppShell
          user={currentUser}
          onLogout={studentLogout}
          onboarding
        >'''

if old_incomplete in app:
    app = app.replace(old_incomplete, new_incomplete, 1)
elif "to={studentPaths.completeProfile}" not in app:
    raise RuntimeError("Não encontrei o bloqueio de cadastro incompleto.")

APP.write_text(app, encoding="utf-8", newline="\n")

profile = PROFILE.read_text(encoding="utf-8")
if 'src="/logo-symbol.png?v=3"' in profile:
    profile = profile.replace(
        'src="/logo-symbol.png?v=3"',
        'src="/logo-symbol-mark.png?v=1"',
        1,
    )
elif 'src="/logo-symbol-mark.png?v=1"' not in profile:
    raise RuntimeError("Não encontrei o símbolo do cabeçalho do perfil.")

PROFILE.write_text(profile, encoding="utf-8", newline="\n")

build = subprocess.run(
    ["npm.cmd", "run", "build"],
    cwd=FRONTEND,
)

if build.returncode:
    raise SystemExit(build.returncode)

print("\nEtapa 70 concluída.")
print(
    "O onboarding agora possui rota própria, "
    "título correto, menu bloqueado e símbolo RC isolado."
)
print("\nExecute:")
print(
    "git add frontend/src/App.jsx "
    "frontend/src/ProfilePanel.jsx "
    "frontend/src/router/paths.js "
    "frontend/src/layout/AppShell.jsx "
    "frontend/src/layout/Sidebar.jsx "
    "frontend/public/logo-symbol-mark.png"
)
print('git commit -m "fix: isola rota e identidade do onboarding"')
print("git push origin main")
